// Block Pop: click (or tap) a group of 2 or more touching blocks of the same color to pop it.
// Blocks above fall into the gap. A group of n blocks scores (n - 1) * (n - 1), so big groups
// pay off. The game ends when no group is left. Arrows / d-pad turn the camera.
// Shows: mouse_set_mode(1), mouse_ray() + mray() to find the block under the cursor,
// mget / mset to change the map while playing, save() / load() for the best score.
// map 0 = the tower; map 1 = the stand under it; tiles 1-4 = the four colors, 5 = the stand

const W = 5, H = 6, D = 5          // tower size in blocks
const PART = [0, 8, 10, 11, 12]    // particle color for each tile
const LIGHT = [0, 14, 7, 26, 6]    // lighter shade of each, to light up the group under the cursor
let ang = 0.1, lift = 0.09         // camera: turns around the tower, and up from level
let score, best = 0, over, hover = [], parts = [], pops = []

function _init() {
  mouse_set_mode(1)                // click mode: the cursor stays free, taps count as clicks
  bg(1)
  map_set_pos(1, [-1, -1, -1])     // the stand sits one block below and around the tower
  let d = load()
  if (d) best = d.best
  newGame()
}

function newGame() {
  for (let z = 0; z < D; z++) for (let y = 0; y < H; y++) for (let x = 0; x < W; x++)
    mset(0, x, y, z, 1 + flr(rnd(4)))
  score = 0; over = false; parts = []; pops = []
}

// every block touching (x, y, z) with the same tile, found by flood fill
function group(x, y, z) {
  let t = mget(0, x, y, z), out = [], seen = {}, todo = [[x, y, z]]
  if (!t) return out
  while (todo.length) {
    let [a, b, c] = todo.pop(), k = a + ',' + b + ',' + c
    if (seen[k] || mget(0, a, b, c) != t) continue
    seen[k] = true
    out.push([a, b, c])
    todo.push([a + 1, b, c], [a - 1, b, c], [a, b + 1, c], [a, b - 1, c], [a, b, c + 1], [a, b, c - 1])
  }
  return out
}

// blocks fall straight down to fill gaps, column by column
function fall() {
  for (let z = 0; z < D; z++) for (let x = 0; x < W; x++) {
    let col = []
    for (let y = 0; y < H; y++) if (mget(0, x, y, z)) col.push(mget(0, x, y, z))
    for (let y = 0; y < H; y++) mset(0, x, y, z, col[y] || 0)
  }
}

function movesLeft() {
  for (let z = 0; z < D; z++) for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    let t = mget(0, x, y, z)
    if (t && (mget(0, x + 1, y, z) == t || mget(0, x, y + 1, z) == t || mget(0, x, y, z + 1) == t)) return true
  }
  return false
}

function pop(g) {
  let t = mget(0, ...g[0]), n = g.length, pts = (n - 1) * (n - 1)
  for (let [x, y, z] of g) {
    mset(0, x, y, z, 0)
    for (let i = 0; i < 3; i++)
      parts.push({ x: x + 0.5, y: y + 0.5, z: z + 0.5, vx: rnd(0.16) - 0.08, vy: rnd(0.12), vz: rnd(0.16) - 0.08, c: PART[t], life: 40 })
  }
  score += pts
  let [mx, my] = mouse_pos()
  pops.push({ x: mx, y: my, text: '+' + pts, life: 40 })
  sfx(n >= 6 ? 1 : 0)
  fall()
  if (!movesLeft()) {
    over = true
    if (score > best) { best = score; save({ best: best }) }
    sfx(3)
  }
}

function _update() {
  // camera: left / right turn around the tower, up / down raise and lower it
  if (btn(0)) ang -= 0.005
  if (btn(1)) ang += 0.005
  if (btn(2)) lift = min(lift + 0.003, 0.2)
  if (btn(3)) lift = max(lift - 0.003, 0.01)

  if (over) {
    hover = []
    if (btnp(4) || btnp(5) || btnp(19)) { newGame(); sfx(4) }
  } else {
    // the block under the cursor: a ray from the camera, then the first block it hits
    let [t, x, y, z] = mray(0, ...mouse_ray())
    hover = t ? group(x, y, z) : []
    if (btnp(19)) {
      if (hover.length >= 2) pop(hover)
      else sfx(2)
    }
  }

  for (let p of parts) { p.x += p.vx; p.y += p.vy; p.z += p.vz; p.vy -= 0.008; p.life-- }
  parts = parts.filter((p) => p.life > 0)
  for (let p of pops) { p.y -= 0.5; p.life-- }
  pops = pops.filter((p) => p.life > 0)
}

function _draw() {
  let cx = W / 2, cy = H / 2 - 0.5, cz = D / 2, r = 9.5
  cam_set_pos([cx + sin(ang) * cos(lift) * r, cy + sin(lift) * r, cz + cos(ang) * cos(lift) * r])
  cam_set_lookat([cx, cy, cz])

  outline(0)
  map(0)
  map(1)
  // light up the group under the cursor: slightly bigger cubes in a lighter shade, outlined in white
  if (hover.length >= 2) {
    outline(7)
    let c = LIGHT[mget(0, ...hover[0])]
    for (let [x, y, z] of hover) cube(x + 0.5, y + 0.5, z + 0.5, 1.04, c)
  }
  outline()
  for (let p of parts) cube(p.x, p.y, p.z, 0.15 * p.life / 40 + 0.05, p.c)

  print('Score ' + score, 4, 4, 7, 0)
  let b = 'Best ' + best
  print(b, 252 - b.length * 7, 4, 10, 0)
  for (let p of pops) print(p.text, p.x - 6, p.y - 14, 10, 0)
  if (over) {
    rectfill(40, 96, 215, 158, 1)
    rect(40, 96, 215, 158, 7)
    print('No more moves!', 79, 104, 10, 0)
    let s = 'Score ' + score + (score >= best && score > 0 ? '  New best!' : '')
    print(s, 128 - s.length * 3.5, 120, 7, 0)
    print('click or O to play again', 44, 138, 6)
  } else {
    print('Click a group of 2+ to pop it', 4, 232, 6, 0)
    print('Arrows turn the camera', 4, 244, 6, 0)
  }
}
